document.addEventListener('DOMContentLoaded',()=>{
 let points=<?=json_encode($savedPoints)?>.map(p=>({x:Math.max(0,+p.x||0),z:Math.max(0,+p.z||0)}));const savedProfileSignature=JSON.stringify([...points].sort((a,b)=>a.x-b.x));
 const svg=document.querySelector('#crossSectionSvg'),drawing=document.querySelector('#sectionDrawing'),rows=document.querySelector('#profilePointRows'),hidden=document.querySelector('#profilePoints'),waterInput=document.querySelector('#simulationWaterLevel'),snapButton=document.querySelector('#toggleSnap'),gridBackground=document.querySelector('#gridBackground'),drawingScale=document.querySelector('#drawingScale'),drawingWidth=document.querySelector('#drawingWidth'),drawingMinElevation=document.querySelector('#drawingMinElevation'),drawingMaxElevation=document.querySelector('#drawingMaxElevation'),display={grid:document.querySelector('#displayGrid'),axes:document.querySelector('#displayAxes'),ticks:document.querySelector('#displayTicks'),pointNames:document.querySelector('#displayPointNames'),pointCoordinates:document.querySelector('#displayPointCoordinates'),waterLine:document.querySelector('#displayWaterLine'),waterFill:document.querySelector('#displayWaterFill')};let dragging=null,snapEnabled=true,drawingEnabled=false;
 const profileSaveStatus=document.createElement('div');let profileDirty=false;const setProfileSaveStatus=()=>{profileSaveStatus.className=`alert ${profileDirty?'alert-warning':'alert-success'} py-2 px-3 small mt-2 mb-0`;profileSaveStatus.innerHTML=profileDirty?'<i class="bi bi-exclamation-triangle-fill"></i> <strong>Perubahan profil belum disimpan.</strong> Web publik masih memakai profil sebelumnya. Tekan <strong>Simpan Penampang & Perhitungan</strong> agar lebar dan luas publik dihitung dari gambar ini.':'<i class="bi bi-check-circle-fill"></i> Profil tersimpan. Web publik menghitung lebar dan luas berdasarkan tinggi air sensor serta profil ini.'};const markProfileDirty=()=>{if(!profileDirty){profileDirty=true;setProfileSaveStatus()}};setProfileSaveStatus();rows.closest('.table-responsive').before(profileSaveStatus);
 const addPointButton=document.querySelector('#addProfilePoint'),bulkPointButton=document.createElement('button'),bulkPointBox=document.createElement('div');bulkPointButton.type='button';bulkPointButton.className='btn btn-outline-success btn-sm me-2';bulkPointButton.innerHTML='<i class="bi bi-clipboard-plus"></i> Tempel dari Excel';addPointButton.before(bulkPointButton);bulkPointBox.className='border rounded-3 bg-light p-3 mt-3 d-none';bulkPointBox.innerHTML='<label class="form-label fw-semibold mb-1" for="bulkPointData">Edit banyak titik / tempel dari Excel</label><small class="d-block text-secondary mb-2">Masukkan dua kolom: <b>Jarak X</b> lalu <b>Elevasi Z</b>. Satu baris untuk satu titik. Nilai Z tidak boleh kurang dari 0.</small><textarea class="form-control font-monospace" id="bulkPointData" rows="7" placeholder="0\t1,20\n0,50\t0,80\n1,20\t0"></textarea><div class="d-flex justify-content-end gap-2 mt-2"><button type="button" class="btn btn-light btn-sm" id="cancelBulkPoints">Batal</button><button type="button" class="btn btn-success btn-sm" id="applyBulkPoints"><i class="bi bi-check2"></i> Terapkan Titik</button></div>';rows.closest('.table-responsive').before(bulkPointBox);const bulkPointData=bulkPointBox.querySelector('#bulkPointData'),applyBulkPoints=bulkPointBox.querySelector('#applyBulkPoints'),cancelBulkPoints=bulkPointBox.querySelector('#cancelBulkPoints');
 bulkPointButton.addEventListener('click',()=>{const open=bulkPointBox.classList.toggle('d-none');if(!open)bulkPointData.focus()});cancelBulkPoints.addEventListener('click',()=>bulkPointBox.classList.add('d-none'));applyBulkPoints.addEventListener('click',()=>{const parsed=bulkPointData.value.split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map((line,index)=>{const cells=line.split(/\t|;/).map(cell=>cell.trim().replace(',','.'));if(cells.length<2||!Number.isFinite(Number(cells[0]))||!Number.isFinite(Number(cells[1])))throw new Error(`Baris ${index+1} harus berisi X dan Z.`);return{x:Math.max(0,Number(cells[0])),z:Math.max(0,Number(cells[1]))}}).sort((a,b)=>a.x-b.x);if(parsed.length<2)return alert('Masukkan minimal dua titik X dan Z.');for(let i=1;i<parsed.length;i++)if(parsed[i].x-parsed[i-1].x<pointGap)return alert(`Jarak X baris ${i+1} terlalu dekat dengan baris sebelumnya. Minimal ${pointGap.toFixed(2)} m agar garis tidak bertumpuk.`);points=parsed;bulkPointBox.classList.add('d-none');bulkPointData.value='';render()});
 const simulationBox=document.querySelector('#webSimulation'),simulationPlay=document.querySelector('#simulationPlay'),simulationReset=document.querySelector('#simulationReset'),simulationSpeed=document.querySelector('#simulationSpeed'),simulationStatus=document.querySelector('#simulationStatus'),simulationSpeedLabel=document.querySelector('#simulationSpeedLabel');
 let simulationSeries=[],simulationIndex=0,simulationTimer=null;
 try{simulationSeries=JSON.parse(simulationBox?.dataset.series||'[]')}catch(_){simulationSeries=[]}
 const simulationRate=()=>Number(simulationSpeed?.value||1);
 const simulationSync=()=>{if(!simulationStatus)return;const row=simulationSeries[simulationIndex];simulationSpeedLabel.textContent=`${String(simulationRate()).replace('.',',')}×`;simulationStatus.textContent=!simulationSeries.length?'Belum ada data tinggi air dari alat yang terhubung.':`Data ${simulationIndex+1}/${simulationSeries.length} · ${row?.at||'—'} · H ${Number(row?.height||0).toFixed(3)} m`};
 const simulationStop=()=>{if(simulationTimer){clearInterval(simulationTimer);simulationTimer=null}if(simulationPlay)simulationPlay.innerHTML='<i class="bi bi-play-fill"></i> Mulai';};
 const simulationStep=()=>{if(!simulationSeries.length)return;simulationIndex=(simulationIndex+1)%simulationSeries.length;waterInput.value=Number(simulationSeries[simulationIndex].height).toFixed(3);render();simulationSync();};
 const simulationStart=()=>{if(!simulationSeries.length)return;simulationStop();simulationStep();simulationTimer=setInterval(simulationStep,Math.max(160,1000/simulationRate()));simulationPlay.innerHTML='<i class="bi bi-pause-fill"></i> Jeda';};
 simulationPlay?.addEventListener('click',()=>simulationTimer?simulationStop():simulationStart());
 simulationReset?.addEventListener('click',()=>{simulationStop();simulationIndex=0;if(simulationSeries[0]){waterInput.value=Number(simulationSeries[0].height).toFixed(3);render()}simulationSync()});
 simulationSpeed?.addEventListener('change',()=>{const wasRunning=!!simulationTimer;simulationStop();simulationSync();if(wasRunning)simulationStart()});
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const water=()=>+waterInput.value||0; const inputNumber=input=>input&&input.value.trim()!==''&&Number.isFinite(Number(input.value))?Number(input.value):null; const bounds=()=>{const xs=points.map(p=>p.x),zs=points.map(p=>p.z),autoMaxX=Math.max(6,...xs),autoMaxZ=Math.max(water(),...zs,1),padX=Math.max(1,autoMaxX*.12),padZ=Math.max(.5,autoMaxZ*.18),manualWidth=inputNumber(drawingWidth),manualMaxZ=inputNumber(drawingMaxElevation);let minX=0,maxX=manualWidth!==null&&manualWidth>0?manualWidth:autoMaxX+padX,minZ=0,maxZ=manualMaxZ===null?autoMaxZ+padZ:Math.max(.1,manualMaxZ);if(maxZ-minZ<.1)maxZ=autoMaxZ+padZ;return {minX,maxX,minZ,maxZ}};
 drawingMinElevation.min='0';
 const project=(p,b)=>({x:55+(p.x-b.minX)/(b.maxX-b.minX)*810,y:395-(p.z-b.minZ)/(b.maxZ-b.minZ)*350});
 const niceStep=value=>{const power=10**Math.floor(Math.log10(Math.max(value,.001))),fraction=value/power,nice=fraction<=1?1:fraction<=2?2:fraction<=5?5:10;return nice*power};
 const axisTicks=b=>{const xStep=niceStep((b.maxX-b.minX)/8),zStep=niceStep((b.maxZ-b.minZ)/7),xZero=project({x:0,z:0},b).x,zZero=project({x:0,z:0},b).y,decimals=step=>Math.max(0,Math.ceil(-Math.log10(step))),format=(value,step)=>Math.abs(value)<1e-8?'0':value.toFixed(decimals(step));let marks='';if(display.ticks.checked){for(let x=Math.ceil(b.minX/xStep)*xStep;x<=b.maxX+1e-8;x+=xStep){const q=project({x,z:0},b);marks+=`<line x1="${q.x}" y1="${zZero-5}" x2="${q.x}" y2="${zZero+5}" stroke="#355a76"/><text x="${q.x}" y="${zZero+20}" text-anchor="middle" fill="#46657d" font-size="11">${format(x,xStep)}</text>`}for(let z=Math.ceil(b.minZ/zStep)*zStep;z<=b.maxZ+1e-8;z+=zStep){const q=project({x:0,z},b);marks+=`<line x1="${xZero-5}" y1="${q.y}" x2="${xZero+5}" y2="${q.y}" stroke="#355a76"/><text x="${xZero-10}" y="${q.y+4}" text-anchor="end" fill="#46657d" font-size="11">${format(z,zStep)}</text>`}}if(display.axes.checked)marks+=`<text x="858" y="${zZero-8}" text-anchor="end" fill="#173b5a" font-size="12" font-weight="700">X (m)</text><text x="${xZero+9}" y="58" fill="#173b5a" font-size="12" font-weight="700">Elevasi Z (m)</text>`;return{xZero,zZero,marks,xStep,zStep}};
 const unproject=(x,y,b)=>({x:Math.max(0,+(b.minX+(x-55)/810*(b.maxX-b.minX)).toFixed(3)),z:Math.max(0,+(b.minZ+(395-y)/350*(b.maxZ-b.minZ)).toFixed(3))});
 const snapPoint=p=>snapEnabled?{x:Math.max(0,Math.round(p.x*10)/10),z:Math.max(0,Math.round(p.z*10)/10)}:{x:Math.max(0,p.x),z:Math.max(0,p.z)};
 const pointGap=0,keepBetweenNeighbors=(candidate,index)=>{const left=index>0?points[index-1].x:0,right=index<points.length-1?points[index+1].x:Infinity;return{x:Math.max(left,Math.min(right,candidate.x)),z:Math.max(0,candidate.z)}};
 const drawButton=document.createElement('button'),drawingHelp=document.querySelector('#crossSectionCad + .d-flex span');drawButton.type='button';drawButton.className='btn btn-outline-success btn-sm';snapButton.before(drawButton);drawingHelp.innerHTML='<i class="bi bi-mouse"></i> Aktifkan <b>Gambar Titik</b> untuk menambah titik · Tarik titik yang ada untuk mengubah posisi';
 const updateDrawButton=()=>{drawButton.classList.toggle('btn-success',drawingEnabled);drawButton.classList.toggle('btn-outline-success',!drawingEnabled);drawButton.setAttribute('aria-pressed',drawingEnabled?'true':'false');drawButton.innerHTML=`<i class="bi bi-${drawingEnabled?'pencil-fill':'pencil'}"></i> Gambar Titik: ${drawingEnabled?'Aktif':'Nonaktif'}`;svg.style.cursor=drawingEnabled?'crosshair':'default'};
 drawButton.addEventListener('click',()=>{drawingEnabled=!drawingEnabled;updateDrawButton()});updateDrawButton();
 const updateSnapButton=()=>{snapButton.classList.toggle('btn-primary',snapEnabled);snapButton.classList.toggle('btn-outline-primary',!snapEnabled);snapButton.innerHTML=`<i class="bi bi-magnet-fill"></i> Snap Grid: ${snapEnabled?'Aktif':'Nonaktif'}`};
 snapButton.addEventListener('click',()=>{snapEnabled=!snapEnabled;updateSnapButton()});updateSnapButton();
 const calc=()=>{if(!points.length)return{area:0,width:0,depth:0,avg:0};const h=water();let area=0,width=0,minZ=Math.min(...points.map(p=>p.z));[...points].sort((a,b)=>a.x-b.x).forEach((a,i,all)=>{const b=all[i+1];if(!b)return;const dx=b.x-a.x,da=h-a.z,db=h-b.z;if(dx<=0||da<=0&&db<=0)return;if(da>=0&&db>=0){area+=(da+db)/2*dx;width+=dx}else{const ratio=da/(da-db),part=dx*(da>0?ratio:1-ratio);area+=.5*Math.max(da,db)*part;width+=part}});const depth=Math.max(0,h-minZ);return{area,width,depth,avg:depth?area/depth:0}};
 const renderRows=()=>{points.sort((a,b)=>a.x-b.x);rows.innerHTML=points.map((p,i)=>`<tr><td>${i+1}</td><td><input class="form-control form-control-sm point-x" data-i="${i}" type="number" step="0.001" min="0" value="${p.x}"></td><td><input class="form-control form-control-sm point-z" data-i="${i}" type="number" step="0.001" min="0" value="${p.z}"></td><td><button class="btn btn-outline-danger btn-sm delete-point" data-i="${i}" type="button" title="Hapus titik"><i class="bi bi-trash"></i></button></td></tr>`).join('');rows.querySelectorAll('.point-x,.point-z').forEach(el=>el.addEventListener('change',()=>{const i=+el.dataset.i,candidate={...points[i]};if(el.classList.contains('point-x'))candidate.x=Math.max(0,+el.value||0);else candidate.z=Math.max(0,+el.value||0);points[i]=keepBetweenNeighbors(candidate,i);render()}));rows.querySelectorAll('.delete-point').forEach(btn=>btn.addEventListener('click',()=>{if(points.length<=2)return alert('Minimal dua titik diperlukan.');points.splice(+btn.dataset.i,1);render()}));};
 const wetPolygon=(ordered,b,h)=>{const under=p=>p.z<=h,cut=(a,c)=>{const t=(h-a.z)/(c.z-a.z);return{x:a.x+(c.x-a.x)*t,z:h}},path=[];ordered.forEach((a,i)=>{const c=ordered[i+1];if(!c)return;const aUnder=under(a),cUnder=under(c);if(aUnder&&!path.length)path.push(a);if(aUnder&&cUnder)path.push(c);else if(aUnder&&!cUnder)path.push(cut(a,c));else if(!aUnder&&cUnder)path.push(cut(a,c),c)});if(path.length<2)return'';const contour=[...path,{x:path.at(-1).x,z:h},{x:path[0].x,z:h}].map(p=>{const q=project(p,b);return`${q.x},${q.y}`}).join(' ');return`<polygon points="${contour}" fill="#38bdf8" fill-opacity=".42" stroke="#0789d1" stroke-width="1.5" stroke-dasharray="5 3"/>`};
 const render=()=>{
  const b=bounds(),h=water(),ordered=[...points].sort((a,b)=>a.x-b.x),axes=axisTicks(b);
  const poly=ordered.map(p=>{const q=project(p,b);return `${q.x},${q.y}`}).join(' ');
  const dots=ordered.map((p,i)=>{const q=project(p,b),name=display.pointNames.checked?`<text x="${q.x+10}" y="${q.y-10}" fill="#173b5a" font-size="13" font-weight="700">T${i+1}</text>`:'',coordinates=display.pointCoordinates.checked?`<text x="${q.x+10}" y="${q.y+7}" fill="#58728a" font-size="10">X ${p.x.toFixed(2)} · Z ${p.z.toFixed(2)}</text>`:'';return `<circle class="profile-dot" data-i="${i}" cx="${q.x}" cy="${q.y}" r="8" fill="#1677c8" stroke="#fff" stroke-width="3"/>${name}${coordinates}`}).join('');
  const waterY=project({x:0,z:h},b).y,wet=display.waterFill.checked?wetPolygon(ordered,b,h):'',waterCenterX=460,waterLabelY=Math.max(34,waterY-22),waterMarker=`<polygon points="${waterCenterX-10},${waterY-16} ${waterCenterX+10},${waterY-16} ${waterCenterX},${waterY-2}" fill="#f59e0b" stroke="#ffffff" stroke-width="2"/><rect x="${waterCenterX-73}" y="${waterLabelY-17}" width="146" height="23" rx="11" fill="#fff7df" stroke="#f59e0b"/><text x="${waterCenterX}" y="${waterLabelY}" text-anchor="middle" fill="#9a5a00" font-size="13" font-weight="700">Tinggi air: ${h.toFixed(3)} m</text>`,axisLines=display.axes.checked?`<line x1="55" y1="${axes.zZero}" x2="865" y2="${axes.zZero}" stroke="#355a76" stroke-width="1.5"/><line x1="${axes.xZero}" y1="45" x2="${axes.xZero}" y2="395" stroke="#355a76" stroke-width="1.5"/>`:'' ,waterLayer=display.waterLine.checked?`<line x1="55" y1="${waterY}" x2="865" y2="${waterY}" stroke="#0789d1" stroke-width="2" stroke-dasharray="8 5"/>${waterMarker}`:'';
  gridBackground.style.display=display.grid.checked?'':'none';drawing.innerHTML=`${axisLines}${axes.marks}${wet}${waterLayer}<polyline points="${poly}" fill="none" stroke="#172e45" stroke-width="4" stroke-linejoin="round"/>${dots}`;drawingScale.textContent=`Area X 0–${b.maxX.toFixed(2)} m · Z ${b.minZ.toFixed(2)}–${b.maxZ.toFixed(2)} m`;
  hidden.value=JSON.stringify(ordered);if(hidden.value!==savedProfileSignature)markProfileDirty();const r=calc();document.querySelector('#wetArea').textContent=r.area.toFixed(3)+' m²';document.querySelector('#averageWidth').textContent=r.avg.toFixed(3)+' m';document.querySelector('#surfaceWidth').textContent=r.width.toFixed(3)+' m';document.querySelector('#maxDepth').textContent=r.depth.toFixed(3)+' m';renderRows();
 };
 svg.addEventListener('pointerdown',e=>{const dot=e.target.closest('.profile-dot');const rect=svg.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*900,y=(e.clientY-rect.top)/rect.height*440;if(dot){dragging=+dot.dataset.i;svg.setPointerCapture(e.pointerId);return}if(!drawingEnabled)return;points.push(snapPoint(unproject(x,y,bounds())));render()});svg.addEventListener('pointermove',e=>{if(dragging===null)return;const rect=svg.getBoundingClientRect(),p=keepBetweenNeighbors(snapPoint(unproject((e.clientX-rect.left)/rect.width*900,(e.clientY-rect.top)/rect.height*440,bounds())),dragging);points[dragging]=p;render()});svg.addEventListener('pointerup',()=>dragging=null);
 document.querySelector('#addProfilePoint').addEventListener('click',()=>{const last=points.at(-1)||{x:0,z:0};points.push({x:last.x+1,z:last.z});render()});document.querySelector('#clearProfile').addEventListener('click',()=>{if(confirm('Kosongkan seluruh titik penampang?')){points=[];render()}});waterInput.addEventListener('input',render);[drawingWidth,drawingMinElevation,drawingMaxElevation,...Object.values(display)].forEach(control=>control?.addEventListener('input',render));render();
});
</script>
